sys_script_include.script:
var CheckScheduleDuplicate = Class.create();
CheckScheduleDuplicate.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    isDuplicate: function() {
        var courseId = this.getParameter('sysparm_course_id');
        var dateStr  = this.getParameter('sysparm_date_id'); 

        if (!courseId || !dateStr) return 'false';

        var parts = dateStr.split('/');
        if (parts.length !== 3) return 'false';

        var day   = parts[0];
        var month = parts[1];
        var year  = parts[2];

        var dateInternal = year + '-' + month + '-' + day; 

        var start = gs.dateGenerate(dateInternal, '00:00:00');
        var end   = gs.dateGenerate(dateInternal, '23:59:59');

        var gr = new GlideRecord('x_752538_course_schedule');
        gr.addQuery('course', courseId);
        gr.addQuery('date', '>=', start);
        gr.addQuery('date', '<=', end);
        gr.query();

        return gr.hasNext() ? 'true' : 'false';
    },

    type: 'CheckScheduleDuplicate'
});
